ALTER TABLE "Timer" ADD CONSTRAINT "Timer_domain" CHECK ("durationMs" BETWEEN 60000 AND 1800000000 AND "version">0 AND "category" IN ('CROP','ANIMAL','LABORER','FOCUS','REMINDER','CUSTOM') AND length("title") BETWEEN 1 AND 100), ADD CONSTRAINT "Timer_state" CHECK (("status"='RUNNING' AND "dueAt" IS NOT NULL AND "remainingMs" IS NULL) OR ("status"='PAUSED' AND "dueAt" IS NULL AND "remainingMs">=0) OR ("status"='COMPLETED' AND "dueAt" IS NULL AND "remainingMs"=0));
ALTER TABLE "ItemMetadata" ADD CONSTRAINT "Metadata_identity" CHECK ("id" ~ '^T[1-8]_[A-Z0-9_]+(@[1-4])?$' AND substring("id" from '^T([1-8])_')::int="tier" AND COALESCE(substring("id" from '@([1-4])$')::int,0)="enchantment"), ADD CONSTRAINT "Metadata_power" CHECK ("itemPower" IS NULL OR "itemPower" BETWEEN 0 AND 5000);
